/* selectMasterMdCpCreditEvaluationExemptionCompanyPopList */
SELECT
	CREDIT_FREE_REASON
FROM ICOMCMPY
WHERE COM_CODE  = #{com_code}

mapper.update:

/* updateMasterMdCpCreditEvaluationExemptionCompanyPop */
UPDATE ICOMCMPY
SET
	CREDIT_STATUS = 'C',
	CREDIT_FREE_REASON  = #{st_appoint_remark}
WHERE COM_CODE  = #{com_code}


/* deleteMasterMdCpCreditEvaluationExemptionCompanyPop */
DELETE FROM ICOMCOD3
WHERE TYPE = 'BTOS'
AND FLAG = 'C'
AND CODE2 = #{com_code}

/* insertMasterMdCpCreditEvaluationExemptionCompanyPop */ INSERT INTO ICOMCOD3 ( BUYER, TYPE, CODE2, CODE1, TEXT1, TEXT2, TEXT3, TEXT4, VALUE1, FLAG, ADD_USER_ID, ADD_DATE ) ( SELECT 'KRKORE0001', 'BTOS', #{com_code},
'ALL', '전체고객사',
COM_CODE, COM_NAME_LOC,
(SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = #{com_code}), '', '', '1', 'C', #{user_id}, TO_CHAR(SYSDATE,'YYYYMMDD') FROM ICOMCMPY WHERE STATUS IN ('C','R')
AND COM_CODE IN ('KRKORE0001' )
AND COM_CODE IN
#{item}
)
